async function api(path, data, method=data===undefined?'GET':'POST') {
 const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),30000);
 try { const response=await fetch('/api'+path,{method,headers:{'Content-Type':'application/json',...(state.tenantId?{'X-Tenant-Id':state.tenantId}:{})},body:data===undefined?undefined:JSON.stringify(data),signal:controller.signal}); const type=response.headers.get('content-type')||''; const result=type.includes('json')?await response.json():{error:await response.text()};if(!response.ok){const error=new Error(result.message || (typeof result.error==='string'?result.error:result.error?.message) || 'درخواست انجام نشد.');error.status=response.status;error.code=result.code;throw error;}return result; }
 catch(err){if(err.name==='AbortError')throw new Error('پاسخ سرور به‌موقع دریافت نشد؛ دوباره تلاش کنید.');throw err;} finally{clearTimeout(timeout);}
}
async function loadIntegrations(){
 const integration=state.integration;if(integration.busy)return;const generation=++integration.generation;integration.loading=true;integration.error='';renderIntegrationPanels();
 try{const data=await api('/integrations');if(generation!==integration.generation)return;integration.data=data;}
 catch(error){if(generation===integration.generation)integration.error=error.message;}
 finally{if(generation===integration.generation){integration.loading=false;renderIntegrationPanels();}}
}
function renderIntegrationPanels(){if(state.view!=='settings'||!state.data)return;const neo=$('#neoIntegrationPanel'),fanasa=$('#fanasaIntegrationPanel');if(neo)neo.outerHTML=neoIntegrationPanel();if(fanasa)fanasa.outerHTML=fanasaIntegrationPanel();}
async function integrationAction(kind,work){const integration=state.integration;if(integration.busy)return;integration.generation++;integration.loading=false;integration.error='';integration.busy=kind;renderIntegrationPanels();try{return await work();}catch(error){integration.error=error.message;throw error;}finally{integration.busy='';renderIntegrationPanels();}}
function rememberImport(row){const integration=state.integration;const data=integration.data||{};const sync=data.sync||data.fanasa||{};const imports=(sync.imports||sync.runs||[]).filter(r=>r.id!==row.id);integration.data={...data,sync:{...sync,imports:[row,...imports].slice(0,20)}};}

async function refresh(render=true){const generation=++state.refreshGeneration;try {const [bootstrap,board]=await Promise.allSettled([api('/bootstrap'),api('/titan/board')]);if(generation!==state.refreshGeneration)return;if(bootstrap.status==='rejected')throw bootstrap.reason;state.data=bootstrap.value;state.error='';state.board=board.status==='fulfilled'?board.value:null;state.boardError=board.status==='rejected'?board.reason.message:'';updateShell();if(!state.wizard)loadWizardDraft();if(render)renderView();if(state.view==='settings')loadIntegrations();}catch(e){if(generation!==state.refreshGeneration)return;state.error=e.message;if(render)renderView();}}
function updateShell(){const pending=$('#pendingCount');if(pending)pending.textContent=nf(list('contracts').filter(c=>c.status==='in_process').length);const count=$('[data-nav-count="contracts"]');if(count)count.textContent=nf(list('contracts').length);const cat=$('[data-nav-count="catalog"]');if(cat)cat.textContent=nf(state.data?.catalog?.services?.length);const tenant=state.tenants.find(t=>t.id===state.tenantId)||state.data?.tenant;$('#workspaceLabel').textContent=state.data?.settings?.workspaceName || state.data?.settings?.organizationName || tenant?.name || 'فضای کاری';$('#workspaceAvatar').textContent=(tenant?.name||'ت').slice(0,1);const picker=$('#tenantSelect');picker.innerHTML=options(state.tenants.map(t=>({value:t.id,label:t.name})),state.tenantId);picker.disabled=state.switchingTenant||!state.tenants.length;$('#accessModeLabel').textContent=state.accessMode==='local-demo'?'محیط محلی آزمایشی':'فضای کاری سازمانی';$('[data-nav-count="titan"]').textContent=nf(state.board?.rows?.length||0);}
