function loadTenantBrowserState(){try{state.selected=new Set(JSON.parse(sessionStorage.getItem(tenantStorageKey('neocontract-selection'))||'[]'));const draft=JSON.parse(sessionStorage.getItem(tenantStorageKey('neocontract-settings-draft'))||'null');state.settingsDraft=draft?.tenantId===state.tenantId?{organizationName:draft.organizationName}:null;}catch{state.selected=new Set();state.settingsDraft=null;}}
