async function switchTenant(id){if(!id||id===state.tenantId)return;if(!state.tenants.some(t=>t.id===id))return;if(state.busy||state.savingSettings||state.integration.busy||state.switchingTenant){$('#tenantSelect').value=state.tenantId;toast('پس از پایان عملیات جاری، فضای کاری را تغییر دهید.','warning');return;}if(state.modal){$('#tenantSelect').value=state.tenantId;requestCloseModal(()=>switchTenant(id));return;}const previousTenantId=state.tenantId;state.switchingTenant=true;persistSelection();persistSettingsDraft(previousTenantId);state.refreshGeneration++;state.integration.generation++;state.detailRequest=(state.detailRequest||0)+1;state.tenantId=id;try{sessionStorage.setItem('neocontract-active-tenant',id);}catch{}Object.assign(state,{data:null,error:'',board:null,boardError:'',wizard:null,draft:null,detail:null,editor:null,settingsDraft:null,settingsSaveError:'',contractFilter:'',contractSearch:'',templateSearch:'',customerSearch:'',catalog:{search:'',center:'',model:'',tier:'',delivery:''},selectedOnly:false,filtersOpen:false,catalogOpen:new Set(['abrgan']),boardFilter:'all',boardCustomer:'',boardSearch:''});state.integration={data:null,loading:false,error:'',generation:state.integration.generation,busy:''};$('#globalSearch').value='';loadTenantBrowserState();updateShell();toggleSidebar(false);renderView();await refresh();state.switchingTenant=false;updateShell();root.focus({preventScroll:true});}
