function resumeWizard(){const saved=state.draft;if(!saved)return;const base=getTemplate(saved.templateId);const version=(base?.versions||[]).find(v=>v.templateVersionId===saved.templateVersionId&&v.status==='published')||publishedTemplates().find(v=>v.id===saved.templateId&&v.templateVersionId===saved.templateVersionId);if(!version){toast('نسخه الگوی این کار در دسترس نیست؛ یک قرارداد تازه از الگوی منتشرشده آغاز کنید.','warning');return;}const missing=saved.services.filter(s=>!getService(s.code));const resume=()=>{state.wizard=clone(saved);state.wizard.step=Math.min(4,Math.max(1,Number(saved.step)||1));state.wizard.services=state.wizard.services.filter(s=>getService(s.code));renderWizard();};if(missing.length){confirmDiscard(resume,'بازبینی سرویس‌های خارج از کاتالوگ',missing.map(s=>s.code).join('، ')+' دیگر در کاتالوگ فعلی موجود نیست. با ادامه، این سرویس‌ها از قرارداد نیمه‌تمام حذف می‌شوند؛ اطلاعات دیگر حفظ می‌شود.');return;}resume();}
